(* CORE_DATA_WIDTH = "128" *) (* DATA_WIDTH = "32" *) (* N = "4" *) 
module Data_controller
   (clk,
    reset,
    din_last,
    din_ready,
    din_valid,
    din_data_core0,
    din_data_core1,
    din_data_core2,
    din_data_core3,
    dout_valid,
    dout_ready,
    dout_data0,
    dout_data1,
    dout_data2,
    dout_data3,
    dout_last,
    reset_cores,
    last_frame);
  input clk;
  input reset;
  input [3:0]din_last;
  input [3:0]din_ready;
  input [3:0]din_valid;
  input [31:0]din_data_core0;
  input [31:0]din_data_core1;
  input [31:0]din_data_core2;
  input [31:0]din_data_core3;
