(* NotValidForBitStream *)
module LDPC_encoder
   (clk,
    reset,
    reset_fifos,
    ldpc_core_clk,
    data_in,
    data_in_valid,
    data_in_ready,
    sel_code_rate,
    end_of_frame,
    data_out0,
    data_out1,
    data_out2,
    data_out3,
    data_out_ready,
    data_out_valid,
    data_out_last,
    last_frame);
  input clk;
  input reset;
  input reset_fifos;
  input ldpc_core_clk;
